  const seed = Number(match[2]);
  if (!SUPPORTED_SIZES.includes(size as BoardSize) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code: value, size: size as BoardSize, seed, deck: makeDeck(size as BoardSize, seed) });
}

function makeDeck(size: BoardSize, seed: number): readonly number[] {
  const cards = Array.from({ length: size * size }, (_, index) => Math.floor(index / 2));
  let state = seed;
  const draw = (bound: number): number => {
    const limit = Math.floor(RANGE / bound) * bound;
    let sample: number;
    do {
      state = (state * 16_807) % MODULUS;
      sample = state - 1;
    } while (sample >= limit);
    return sample % bound;
  };
  for (let index = cards.length - 1; index > 0; index -= 1) {
    const other = draw(index + 1);
    [cards[index], cards[other]] = [cards[other]!, cards[index]!];
  }
  return Object.freeze(cards);
}

export function isSupportedSize(value: unknown): value is BoardSize {
  return typeof value === 'number' && SUPPORTED_SIZES.includes(value as BoardSize);
}

